import { headers } from "next/headers";

import { serializeJsonLd, type JsonLd } from "@/lib/seo/json-ld";

/**
 * Structured data block. `application/ld+json` is data, not script, but it still carries the request's CSP
 * nonce so every <script> element in the document is accounted for (e2e/csp.spec.ts). This is the only
 * dangerouslySetInnerHTML in the public site: the content is generated by serializeJsonLd, which escapes
 * `<`, `>`, `&`, U+2028 and U+2029, so campaign text cannot close the element or inject markup.
 */
export async function JsonLdScript({ data }: { data: JsonLd }) {
  const nonce = (await headers()).get("x-nonce") ?? undefined;
  return <script type="application/ld+json" nonce={nonce} dangerouslySetInnerHTML={{ __html: serializeJsonLd(data) }} />;
}
